# -*- coding: utf-8 -*-
# Layers of Qatar — Explorer-mode stories and AI connections (hypotheses).
# All facts come from qa/data.json records; 'imag' stories use invented characters only.

P = lambda en, ar: {'en': en, 'ar': ar}

def m(t, x, y, s=1, flip=False):
    d = {'t': t, 'x': x, 'y': y, 's': s}
    if flip: d['flip'] = True
    return d

def who(t, x, y, pose='stand', hat=None, s=1, flip=False, back=False, step=0):
    d = {'t': t, 'x': x, 'y': y, 's': s, 'pose': pose, 'hat': hat, 'step': step}
    if flip: d['flip'] = True
    if back: d['back'] = True
    return d

def scene(bg='day', ground='sand', horizon=160, sun=None, back=None, el=None, people=None, front=None, bubble=None):
    d = {'bg': bg, 'ground': ground, 'horizon': horizon}
    if sun: d['sun'] = sun
    if back: d['back'] = back
    if el: d['el'] = el
    if people: d['people'] = people
    if front: d['front'] = front
    if bubble: d['bubble'] = bubble
    return d

LAB = lambda people=None: scene('wall', 'floor', 170, el=[m('lab', 150, 235, 1.1), m('map', 340, 230, 1)], people=people)

